"""Original synthetic CVs: Markdown + self-contained HTML + valid DOCX. No dependencies/network."""
import json,html,zipfile,xml.etree.ElementTree as ET
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
OUT=ROOT/'docs'/'sample-cvs'
PROFILES=[
 ('01-frontend','Nguyễn Minh An','Frontend React',['HTML','CSS','JavaScript','React','REST API'],'Website thương mại điện tử','Thiết kế giao diện danh mục, tìm kiếm và giỏ hàng bằng React; chia component, kiểm tra biểu mẫu và thử màn hình nhỏ.','Trong bài tập nhóm 3 người, phụ trách giao diện và phối hợp thống nhất dữ liệu API. Chưa có kinh nghiệm làm việc chính thức.',3.2),
 ('02-backend','Trần Quốc Bình','Backend Node.js',['JavaScript','Node.js','Express','MongoDB','REST API','Git'],'Cổng tuyển dụng và quản lý hồ sơ','Làm API tạo hồ sơ, tìm kiếm có phân trang và phân quyền theo người sở hữu. Thực hành validate đầu vào và ghi log lỗi đã bỏ dữ liệu riêng tư.','Bài tập quản lý thư viện: tự thiết kế dữ liệu và API, nhờ bạn cùng nhóm kiểm tra các trường hợp thiếu dữ liệu.',3.05),
 ('03-fullstack','Lê Thu Chi','Full-stack',['React','JavaScript','Node.js','MongoDB','Git'],'Website thương mại điện tử','Xây dựng luồng danh sách, tạo và sửa sản phẩm trong bài tập, kết nối React với API Node.js, dùng MongoDB lưu dữ liệu.','Làm đồ án môn học nhóm 4 người, nhận cả phần giao diện lẫn một số API; cần được hướng dẫn thêm transaction và triển khai vận hành.',3.3),
 ('04-qa','Phạm Gia Duy','Kiểm thử phần mềm',['Manual Testing','Test Cases','Postman','API Testing','SQL'],'Ứng dụng theo dõi kho','Viết test case nhập/xuất/tồn, chuẩn bị dữ liệu hợp lệ và dữ liệu lỗi; dùng Postman gọi API, so sánh với kết quả mong đợi.','Bài tập kiểm thử ứng dụng quản lý kho: phụ trách thiết kế ca, báo lỗi rõ bước tái hiện; chưa có chứng chỉ hoặc kinh nghiệm QA chính thức.',2.9),
 ('05-data','Hoàng Ngọc Hà','Phân tích dữ liệu',['Python','SQL','Pandas','Excel','Power BI'],'Dashboard phân tích doanh thu','Làm sạch bảng doanh thu tổng hợp, xử lý giá trị thiếu, nhóm theo tháng/sản phẩm và tạo biểu đồ giải thích số liệu.','Bài tập môn phân tích dữ liệu, dùng dữ liệu tự tạo; không công bố kết quả đó là doanh thu của doanh nghiệp thật.',3.45),
 ('06-ai-nlp','Vũ Minh Khang','AI và xử lý ngôn ngữ',['Python','Pandas','SQL','NLP'],'Dashboard phân tích dữ liệu và nội dung','Thực hành chuẩn hóa văn bản tiếng Việt, tách tập theo người viết, đối chiếu TF-IDF và đọc về embedding; chưa huấn luyện mô hình trên dữ liệu doanh nghiệp.','Bài tập phân loại câu với dữ liệu tổng hợp; hiểu cần có nhãn độc lập trước khi công bố độ chính xác. Mong muốn học thêm đánh giá mô hình.',3.25),
 ('07-blockchain','Đặng Bảo Linh','Blockchain và Backend',['JavaScript','Node.js','Solidity','ethers.js','Git'],'Dịch vụ Backend và lưu bằng chứng','Viết contract lưu hash trong bài tập Hardhat local, kiểm tra quyền ghi và đọc receipt; không sử dụng mainnet hoặc tài sản thật.','Bài tập cá nhân về quyền ghi và replay; chưa có chứng chỉ, audit bảo mật hoặc sản phẩm blockchain đã triển khai công khai.',3.0),
 ('08-beginner','Bùi Thanh Nam','Sinh viên ít kinh nghiệm',['HTML','CSS','Git'],'Giao diện web và hỗ trợ kiểm thử','Làm trang giới thiệu bằng HTML/CSS, bố cục đơn giản và sử dụng Git ở mức commit/branch trong bài tập. Chưa biết React hoặc lập trình API.','Mới hoàn thành học phần lập trình web cơ bản, cần người hướng dẫn chia việc nhỏ và góp ý thường xuyên.',2.55),
]
W='http://schemas.openxmlformats.org/wordprocessingml/2006/main'
def docx(file,lines):
 ET.register_namespace('w',W);doc=ET.Element('{'+W+'}document');body=ET.SubElement(doc,'{'+W+'}body')
 for line in lines:
  p=ET.SubElement(body,'{'+W+'}p');r=ET.SubElement(p,'{'+W+'}r');t=ET.SubElement(r,'{'+W+'}t');t.text=line
 types='<?xml version="1.0"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/></Types>'
 rels='<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/></Relationships>'
 with zipfile.ZipFile(file,'x',compression=zipfile.ZIP_DEFLATED) as z:z.writestr('[Content_Types].xml',types);z.writestr('_rels/.rels',rels);z.writestr('word/document.xml',ET.tostring(doc,encoding='utf-8',xml_declaration=True))
def main():
 OUT.mkdir(parents=True,exist_ok=True);manifest=[]
 for slug,name,track,skills,topic,project,experience,gpa in PROFILES:
  sections=[('HỒ SƠ THỰC TẬP',f'{name} — {track}\nLiên hệ tổng hợp: {slug}@example.invalid\nDữ liệu tổng hợp để thử upload và gợi ý; không phải hồ sơ người thật.'),('MỤC TIÊU VÀ ĐỊNH HƯỚNG',f'Tìm công việc thực tập về {track.lower()}, nhận nhiệm vụ vừa sức, trao đổi tiến độ mỗi tuần và hoàn thiện một phần việc có thể kiểm tra. Mong muốn củng cố nền tảng và học cách làm việc có trách nhiệm.'),('HỌC VẤN',f'Sinh viên Công nghệ thông tin, năm 3–4 trong tình huống học tập tổng hợp. GPA minh họa {gpa}/4. Không sử dụng trường, chứng chỉ hoặc thành tích giả như thông tin đã được xác minh.'),('KỸ NĂNG CHUYÊN MÔN',', '.join(skills)+'.\nMức kinh nghiệm: đã thực hành trong các bài tập nêu bên dưới; chưa được đánh giá bằng phỏng vấn hoặc sản phẩm doanh nghiệp.'),('DỰ ÁN HỌC TẬP VÀ VAI TRÒ',project),('KINH NGHIỆM',experience),('PHỐI HỢP, TRÁCH NHIỆM VÀ CÁCH GIẢI QUYẾT KHÓ KHĂN','Tự khai báo: sẵn sàng tiếp nhận góp ý, chủ động báo khi gặp lỗi và hoàn thành phần việc đúng hạn. Trong bài tập nhóm, thống nhất đầu vào/đầu ra trước khi làm, ghi bước tái hiện lỗi và nhờ hỗ trợ khi chưa tìm ra nguyên nhân. Chưa coi sự siêng năng hoặc khả năng giao tiếp là phẩm chất đã được kiểm chứng.'),('THỜI GIAN VÀ HÌNH THỨC THỰC TẬP','Có thể bố trí 4 ngày/tuần, trong 12 tuần kể từ lịch nhà trường cho phép; lịch cụ thể cần thỏa thuận với doanh nghiệp. Mong muốn làm theo nhóm, có trao đổi hằng tuần và nhận xét rõ phần cần cải thiện.'),('GIỚI HẠN VÀ PHẦN CẦN HỌC THÊM','Chưa có kinh nghiệm vận hành hệ thống thật; cần hướng dẫn kiểm thử, bảo mật và kiểm tra sản phẩm. Không đính kèm repository, chứng chỉ, ảnh hoặc liên kết sản phẩm không tồn tại. Nội dung là bài thực hành, không phải bằng chứng đã làm việc tại doanh nghiệp.')]
  md='\n\n'.join('## '+title+'\n'+body for title,body in sections)+'\n';lines=[line for title,body in sections for line in [title,*body.splitlines(),'']]
  for ext in ['md','html','docx']:
   if (OUT/(slug+'.'+ext)).exists():raise SystemExit('Refuse overwrite: '+slug+'.'+ext)
  (OUT/(slug+'.md')).write_text(md,encoding='utf-8');(OUT/(slug+'.html')).write_text('<!doctype html><html lang="vi"><meta charset="utf-8"><title>'+html.escape(name)+'</title><style>@page{size:A4;margin:16mm}body{font:11pt Arial;line-height:1.4;color:#17213a}h2{font-size:13pt;color:#4338ca;margin-bottom:6px;break-after:avoid}p{white-space:pre-wrap;margin-top:0}section{break-inside:avoid}</style>'+''.join('<section><h2>'+html.escape(t)+'</h2><p>'+html.escape(b)+'</p></section>' for t,b in sections)+'</html>',encoding='utf-8');docx(OUT/(slug+'.docx'),lines);manifest.append(dict(slug=slug,name=name,track=track,skills=skills,gpa=gpa,topic=topic,synthetic=True,expertLabel=False))
 (OUT/'manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n',encoding='utf-8');print('Created 8 Markdown, HTML and DOCX sources; PDFs generated separately with installed Edge.')
if __name__=='__main__':main()
